recipes=[]
def add(id,title,sub,cat,mins,serv,season,allergens,items,steps):
 recipes.append(dict(id=id,title=tr(*title),intro=tr(*sub),category=cat,minutes=mins,servings=serv,seasons=season,allergens=tr(*allergens),ingredients=[dict(id=a,amount=b,unit=c,name=ing[a]) for a,b,c in items],steps=[dict(text=tr(*t),seconds=s) for s,t in steps]))
add('cupcake',('Vanilla cloud cupcakes','Vanille-Wolkenküchlein','Cupcakes nuage à la vanille','Cupcakes nuvem de baunilha'),('A soft crumb, a swirl of pink, a little joy.','Zarte Küchlein mit rosa Creme für kleine Genussmomente.','Une mie tendre et une touche de crème rose.','Massa macia e uma delicada cobertura rosa.'),'cake',45,6,[1,2,3,4],('Wheat, eggs, milk.','Weizen, Eier, Milch.','Blé, œufs, lait.','Trigo, ovos, leite.'),[('flour',120,'g'),('sugar',90,'g'),('butter',120,'g'),('egg',1,'piece'),('milk',60,'ml'),('bakingpowder',1,'tsp'),('vanilla',1,'tsp'),('icingsugar',100,'g'),('berries',30,'g')],[
(0,('Heat a conventional oven to 175°C. Line a six-hole muffin tin. Set aside 60 g of the butter for the frosting.','Backofen auf 175 °C Ober-/Unterhitze vorheizen. Sechs Muffinmulden auslegen. 60 g Butter für die Creme beiseitestellen.','Préchauffez le four traditionnel à 175 °C. Garnissez six moules de caissettes. Réservez 60 g de beurre pour la crème.','Preaqueça o forno convencional a 175 °C. Forre seis formas de cupcake. Reserve 60 g da manteiga para a cobertura.')),
(0,('Beat the remaining 60 g soft butter with the sugar until pale. Beat in the egg and vanilla.','Übrige 60 g weiche Butter mit Zucker hell aufschlagen. Ei und Vanille unterrühren.','Fouettez les 60 g de beurre mou restants avec le sucre. Ajoutez l’œuf et la vanille.','Bata os 60 g restantes de manteiga macia com o açúcar. Junte o ovo e a baunilha.')),
(0,('Fold in flour and baking powder, alternating with milk. Divide between the cases, filling each two-thirds full.','Mehl und Backpulver abwechselnd mit Milch unterheben. Förmchen zu zwei Dritteln füllen.','Incorporez farine et levure en alternant avec le lait. Remplissez les caissettes aux deux tiers.','Incorpore a farinha e o fermento alternando com o leite. Encha as formas até dois terços.')),
(1200,('Bake for 18–20 minutes, until a skewer comes out clean. Cool completely before frosting.','18–20 Minuten backen, bis die Stäbchenprobe sauber ist. Vor dem Verzieren ganz abkühlen lassen.','Faites cuire 18 à 20 minutes, jusqu’à ce qu’une pique ressorte propre. Laissez refroidir complètement.','Asse por 18–20 minutos, até um palito sair limpo. Espere esfriar completamente.')),
(0,('Beat reserved butter with icing sugar. Mash the berries, strain, and add a few drops to tint the cream. Spread or pipe onto the cool cakes. Refrigerate and eat within 2 days.','Reservierte Butter mit Puderzucker aufschlagen. Beeren zerdrücken, passieren und die Creme mit etwas Saft färben. Auf die kalten Küchlein geben. Kühl lagern und binnen 2 Tagen essen.','Fouettez le beurre réservé et le sucre glace. Écrasez et filtrez les fruits, puis ajoutez quelques gouttes pour colorer. Décorez les gâteaux froids. Conservez au frais et consommez sous 2 jours.','Bata a manteiga reservada com o açúcar de confeiteiro. Amasse e coe as frutas; use algumas gotas para colorir. Cubra os bolinhos frios. Refrigere e consuma em até 2 dias.'))])
add('brownie',('Fudgy cocoa brownies','Saftige Schoko-Brownies','Brownies fondants au cacao','Brownies cremosos de cacau'),('Deep chocolate. Crisp edges. A soft middle.','Viel Schokolade, knuspriger Rand, weicher Kern.','Du chocolat intense, un cœur tendre.','Chocolate intenso e um centro macio.'),'quick',40,8,[1,4],('Wheat, eggs, milk. Check chocolate label.','Weizen, Eier, Milch. Schokoladenetikett prüfen.','Blé, œufs, lait. Vérifiez le chocolat.','Trigo, ovos, leite. Confira o rótulo do chocolate.'),[('chocolate',150,'g'),('butter',100,'g'),('sugar',140,'g'),('egg',2,'piece'),('flour',60,'g'),('cocoa',20,'g')],[
(0,('Heat a conventional oven to 175°C. Line a 20 cm square tin with baking paper.','Backofen auf 175 °C Ober-/Unterhitze vorheizen. Eine 20-cm-Form mit Backpapier auslegen.','Préchauffez le four traditionnel à 175 °C. Chemisez un moule carré de 20 cm.','Preaqueça o forno convencional a 175 °C. Forre uma forma quadrada de 20 cm.')),
(0,('Melt chocolate and butter in a bowl over gently simmering water. Remove from heat and cool for 5 minutes.','Schokolade und Butter über einem sanft siedenden Wasserbad schmelzen. Vom Herd nehmen und 5 Minuten abkühlen lassen.','Faites fondre chocolat et beurre au bain-marie doux. Retirez du feu et laissez tiédir 5 minutes.','Derreta o chocolate e a manteiga em banho-maria suave. Retire do fogo e deixe amornar por 5 minutos.')),
(0,('Whisk eggs and sugar for 2 minutes. Stir in the chocolate mixture, then fold in flour and cocoa just until combined.','Eier und Zucker 2 Minuten aufschlagen. Schokoladenmasse einrühren, dann Mehl und Kakao kurz unterheben.','Fouettez œufs et sucre 2 minutes. Incorporez le chocolat, puis délicatement farine et cacao.','Bata os ovos e o açúcar por 2 minutos. Misture o chocolate e incorpore a farinha e o cacau sem bater demais.')),
(1500,('Spread in the tin. Bake 22–25 minutes: edges should be set and a skewer should carry moist crumbs, not raw batter.','In die Form geben. 22–25 Minuten backen: Der Rand soll fest sein, am Stäbchen dürfen feuchte Krümel, aber kein roher Teig haften.','Versez dans le moule. Cuisez 22 à 25 minutes : les bords sont pris et une pique porte des miettes humides, pas de pâte crue.','Espalhe na forma. Asse por 22–25 minutos: as bordas devem estar firmes e o palito com migalhas úmidas, sem massa crua.')),
(0,('Cool fully in the tin before cutting into 8 squares. Keep in an airtight container for up to 3 days.','In der Form ganz abkühlen lassen und in 8 Stücke schneiden. Luftdicht bis zu 3 Tage aufbewahren.','Laissez refroidir dans le moule et coupez en 8 carrés. Conservez dans une boîte hermétique jusqu’à 3 jours.','Deixe esfriar na forma e corte em 8 quadrados. Guarde em recipiente fechado por até 3 dias.'))])
add('lemon',('Sunday lemon loaf','Sonntags-Zitronenkuchen','Cake au citron du dimanche','Bolo de limão de domingo'),('Bright citrus under a delicate lemon glaze.','Frische Zitrone unter einer feinen Glasur.','Un cake lumineux au glaçage délicat.','Sabor cítrico com uma cobertura delicada.'),'cake',65,8,[1,2],('Wheat, eggs, milk.','Weizen, Eier, Milch.','Blé, œufs, lait.','Trigo, ovos, leite.'),[('flour',180,'g'),('butter',120,'g'),('sugar',130,'g'),('egg',2,'piece'),('milk',60,'ml'),('lemon',1,'piece'),('bakingpowder',1.5,'tsp'),('icingsugar',80,'g')],[
(0,('Heat a conventional oven to 170°C. Grease and line a 20 × 10 cm loaf tin. Wash and zest the lemon; reserve the juice.','Backofen auf 170 °C Ober-/Unterhitze vorheizen. Eine 20 × 10 cm Kastenform auslegen. Zitrone waschen und abreiben, Saft aufbewahren.','Préchauffez le four traditionnel à 170 °C. Chemisez un moule à cake de 20 × 10 cm. Lavez et zestez le citron ; réservez le jus.','Preaqueça o forno convencional a 170 °C. Unte e forre uma forma de 20 × 10 cm. Lave e raspe o limão; reserve o suco.')),
(0,('Beat soft butter, sugar and zest until light. Add eggs one at a time, beating after each.','Weiche Butter, Zucker und Abrieb hell aufschlagen. Eier einzeln unterrühren.','Fouettez beurre mou, sucre et zeste. Ajoutez les œufs un à un en fouettant.','Bata a manteiga macia, o açúcar e as raspas. Adicione os ovos, um de cada vez.')),
(0,('Fold in flour and baking powder with the milk. Spoon into the tin and level the surface.','Mehl und Backpulver mit Milch unterheben. In die Form füllen und glatt streichen.','Incorporez farine et levure avec le lait. Versez dans le moule et lissez.','Incorpore a farinha e o fermento com o leite. Coloque na forma e nivele.')),
(2700,('Bake for 40–45 minutes, until golden and a skewer comes out clean. Cool for 10 minutes in the tin, then transfer to a rack.','40–45 Minuten goldgelb backen; Stäbchenprobe machen. 10 Minuten in der Form, dann auf einem Gitter abkühlen lassen.','Cuisez 40 à 45 minutes, jusqu’à ce qu’une pique ressorte propre. Laissez 10 minutes dans le moule, puis sur une grille.','Asse por 40–45 minutos, até dourar e um palito sair limpo. Espere 10 minutos na forma e transfira para uma grade.')),
(0,('Mix icing sugar with 1–2 tablespoons lemon juice to make a thick glaze. Spoon over the cold loaf. Keep covered for up to 3 days.','Puderzucker mit 1–2 EL Zitronensaft zu einer dicken Glasur rühren. Über den kalten Kuchen geben. Abgedeckt bis zu 3 Tage lagern.','Mélangez le sucre glace avec 1 à 2 cuillères à soupe de jus. Nappez le cake froid. Conservez couvert jusqu’à 3 jours.','Misture o açúcar de confeiteiro com 1–2 colheres de sopa de suco. Cubra o bolo frio. Guarde coberto por até 3 dias.'))])
add('berry',('Berry yogurt cups','Beeren-Joghurtgläser','Verrines aux fruits rouges','Taças de iogurte e frutas'),('A cool, no-bake dessert in ten minutes.','Ein kühles Dessert ohne Backen in zehn Minuten.','Un dessert frais sans cuisson en dix minutes.','Uma sobremesa fresca sem forno em dez minutos.'),'nobake',10,2,[2,3],('Milk, oats. Honey is unsuitable for babies under 12 months.','Milch, Hafer. Honig ist für Babys unter 12 Monaten ungeeignet.','Lait, avoine. Pas de miel avant 12 mois.','Leite, aveia. Mel não é indicado para menores de 12 meses.'),[('yogurt',300,'g'),('berries',200,'g'),('honey',1,'tbsp'),('oats',30,'g')],[
(0,('Wash the berries and pat dry. Reserve a few for the top; gently crush the rest with a fork.','Beeren waschen und trocken tupfen. Einige zum Garnieren aufbewahren, übrige mit einer Gabel zerdrücken.','Lavez et séchez les fruits. Réservez-en quelques-uns et écrasez le reste à la fourchette.','Lave e seque as frutas. Reserve algumas para decorar e amasse o restante com um garfo.')),
(0,('Stir honey into the yogurt. Divide half the yogurt between two clean glasses.','Honig in den Joghurt rühren. Die Hälfte auf zwei saubere Gläser verteilen.','Mélangez miel et yaourt. Répartissez la moitié dans deux verres propres.','Misture o mel ao iogurte. Divida metade entre dois copos limpos.')),
(0,('Add the crushed berries, then the remaining yogurt. Scatter oats and whole berries over the top.','Zerdrückte Beeren, dann restlichen Joghurt einschichten. Mit Haferflocken und ganzen Beeren bestreuen.','Ajoutez les fruits écrasés, puis le yaourt restant. Parsemez d’avoine et de fruits entiers.','Adicione as frutas amassadas e o iogurte restante. Cubra com aveia e as frutas inteiras.')),
(0,('Serve immediately, or cover and refrigerate for up to 24 hours. Add oats just before serving if you prefer a firmer texture.','Sofort servieren oder abgedeckt bis zu 24 Stunden kühlen. Für festere Flocken diese erst vor dem Servieren zugeben.','Servez aussitôt ou couvrez et réfrigérez jusqu’à 24 heures. Pour garder la texture, ajoutez l’avoine au dernier moment.','Sirva na hora ou cubra e refrigere por até 24 horas. Para manter a textura, acrescente a aveia apenas ao servir.'))])
add('cookie',('Honey oat cookies','Honig-Hafer-Kekse','Biscuits avoine et miel','Biscoitos de aveia e mel'),('Golden little cookies for the afternoon table.','Goldene kleine Kekse zum Nachmittagskaffee.','Des biscuits dorés pour le goûter.','Biscoitos dourados para o lanche.'),'quick',30,12,[1,3,4],('Wheat, oats, milk. No honey for babies under 12 months.','Weizen, Hafer, Milch. Kein Honig für Babys unter 12 Monaten.','Blé, avoine, lait. Pas de miel avant 12 mois.','Trigo, aveia, leite. Sem mel para menores de 12 meses.'),[('oats',120,'g'),('flour',80,'g'),('butter',80,'g'),('honey',3,'tbsp'),('sugar',40,'g'),('bakingpowder',0.5,'tsp'),('milk',30,'ml')],[
(0,('Heat a conventional oven to 180°C. Line two baking trays. Mix oats, flour, sugar and baking powder.','Backofen auf 180 °C Ober-/Unterhitze vorheizen. Zwei Bleche auslegen. Haferflocken, Mehl, Zucker und Backpulver mischen.','Préchauffez le four traditionnel à 180 °C. Chemisez deux plaques. Mélangez avoine, farine, sucre et levure.','Preaqueça o forno convencional a 180 °C. Forre duas assadeiras. Misture a aveia, a farinha, o açúcar e o fermento.')),
(0,('Melt butter with honey over low heat. Remove from heat, stir in milk and add to the dry mixture.','Butter mit Honig bei kleiner Hitze schmelzen. Vom Herd nehmen, Milch einrühren und zu den trockenen Zutaten geben.','Faites fondre beurre et miel à feu doux. Hors du feu, ajoutez le lait puis mélangez aux ingrédients secs.','Derreta a manteiga com o mel em fogo baixo. Retire do fogo, junte o leite e misture aos ingredientes secos.')),
(0,('Shape 12 small balls. Place well apart on the trays and flatten lightly with your palm.','12 kleine Kugeln formen. Mit Abstand auf die Bleche legen und leicht flach drücken.','Formez 12 petites boules. Espacez-les sur les plaques et aplatissez légèrement.','Forme 12 bolinhas. Coloque nas assadeiras com espaço entre elas e achate levemente.')),
(900,('Bake for 12–15 minutes until golden at the edges. Cookies will firm up as they cool.','12–15 Minuten backen, bis die Ränder goldbraun sind. Die Kekse werden beim Abkühlen fester.','Cuisez 12 à 15 minutes jusqu’à ce que les bords dorent. Les biscuits se raffermissent en refroidissant.','Asse por 12–15 minutos, até dourar nas bordas. Os biscoitos ficam firmes ao esfriar.')),
(0,('Cool on the trays for 5 minutes, then on a rack. Keep airtight for up to 4 days.','5 Minuten auf dem Blech, dann auf einem Gitter abkühlen lassen. Luftdicht bis zu 4 Tage lagern.','Laissez 5 minutes sur les plaques, puis sur une grille. Gardez en boîte hermétique jusqu’à 4 jours.','Espere 5 minutos na assadeira e transfira para uma grade. Guarde em pote fechado por até 4 dias.'))])
add('apple',('Orchard apple cake','Apfelkuchen vom Obstgarten','Gâteau aux pommes du verger','Bolo de maçã do pomar'),('Tender apple slices with a touch of cinnamon.','Zarte Apfelscheiben mit einem Hauch Zimt.','Des pommes fondantes et une touche de cannelle.','Fatias macias de maçã com um toque de canela.'),'cake',60,8,[3,4],('Wheat, eggs, milk.','Weizen, Eier, Milch.','Blé, œufs, lait.','Trigo, ovos, leite.'),[('apple',2,'piece'),('flour',180,'g'),('sugar',120,'g'),('butter',100,'g'),('egg',2,'piece'),('milk',60,'ml'),('bakingpowder',1.5,'tsp'),('cinnamon',1,'tsp')],[
(0,('Heat a conventional oven to 175°C. Grease and line a 20 cm round tin. Core apples and cut into thin slices.','Backofen auf 175 °C Ober-/Unterhitze vorheizen. Eine 20-cm-Springform auslegen. Äpfel entkernen und dünn schneiden.','Préchauffez le four traditionnel à 175 °C. Chemisez un moule rond de 20 cm. Évidez et émincez les pommes.','Preaqueça o forno convencional a 175 °C. Unte e forre uma forma redonda de 20 cm. Retire o miolo das maçãs e corte em fatias finas.')),
(0,('Beat soft butter and sugar until pale. Beat in the eggs one at a time.','Weiche Butter und Zucker hell aufschlagen. Eier einzeln unterrühren.','Fouettez beurre mou et sucre. Incorporez les œufs un à un.','Bata a manteiga macia com o açúcar. Junte os ovos, um de cada vez.')),
(0,('Fold in flour, baking powder and cinnamon, alternating with milk. Spread the batter in the tin.','Mehl, Backpulver und Zimt abwechselnd mit Milch unterheben. Teig in der Form verteilen.','Incorporez farine, levure et cannelle en alternant avec le lait. Étalez la pâte dans le moule.','Incorpore a farinha, o fermento e a canela alternando com o leite. Espalhe a massa na forma.')),
(2400,('Arrange apple slices on top. Bake for 35–40 minutes, until a skewer through the cake comes out clean.','Apfelscheiben darauflegen. 35–40 Minuten backen, bis die Stäbchenprobe sauber ist.','Disposez les pommes dessus. Cuisez 35 à 40 minutes, jusqu’à ce qu’une pique dans la pâte ressorte propre.','Disponha as maçãs por cima. Asse por 35–40 minutos, até um palito inserido na massa sair limpo.')),
(0,('Cool for 15 minutes before removing from the tin. Enjoy warm or cold. Cover and refrigerate for up to 3 days.','Vor dem Herausnehmen 15 Minuten abkühlen lassen. Warm oder kalt genießen. Abgedeckt bis zu 3 Tage im Kühlschrank lagern.','Laissez tiédir 15 minutes avant de démouler. Servez tiède ou froid. Couvrez et réfrigérez jusqu’à 3 jours.','Espere 15 minutos antes de desenformar. Sirva morno ou frio. Cubra e refrigere por até 3 dias.'))])
